                      EXDATE:20260116T000000Z\r\n\
                      EXDATE:20260118T000000Z\r\n\
                      SUMMARY:Multi Exdate Series\r\n\
                      END:VEVENT\r\n\
                      END:VCALENDAR\r\n";
    let (delete_status, _, delete_response) = put_update_request(
