        .status(user_id)
        .await
        .unwrap()
        .principal_id
        .unwrap();
    let calendar_id = create_calendar(&pool, user_id).await;
    // Create the event but do NOT create a DAV mapping up front.
    create_event(&pool, user_id, calendar_id).await;

